INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Princípio do Evangelho de Jesus Cristo, Filho de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'Conforme está escrito no profeta Isaías: Eis que envio o meu anjo ante a tua presença, o qual preparará o teu caminho (Ml. 3, 1).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas (Is. 40, 3).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Apareceu João Batista no deserto, pregando o batismo de penitência, para remissão dos pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'E ia ter com ele toda a região da Judeia e todos os de Jerusalém, e eram baptizados por ele no rio Jordão, confessando os seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'João andava vestido de pêlo de camelo, trazia uma cinta de couro em volta dos rins, alimentava-se de gafanhotos e de mel silvestre. E pregava, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, '"Vem após de mim quem é mais forte do que eu, ao qual eu não sou digno de desatar, prostrado em terra, a correia doa sapatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Eu tenho-vos baptizado em água, ele, porém, baptizar-vos-á no Espírito Santo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Ora aconteceu naqueles dias que Jesus veio de Nazaré da Galileia, e foi baptizado por João no Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'No momento de sair da água, viu os céus abertos, e o Espírito Santo que descia sobre ele em forma de pomba;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'e ouviu-se dos céus uma voz: "Tu és o meu Filho amado, em ti pus as minhas complacências."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Imediamente o Espírito o impeliu para o deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'E permaneceu no deserto quarenta dias, sendo tentado por Satanás. Vivia entre os animais selvagens, e os anjos o serviam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'Depois que João foi preso, foi Jesus para a Galileia, pregando o Evangelho de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'e dizendo: "Está completo o tempo e aproxima-se o reino de Deus; fazei penitência, crede no Evangelho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'Passando ao longo do mar da Galileia, viu Simão e André, seu irmão, que lançavam as redes ao mar, pois eram pescadores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Jesus disse-lhes: "Segui-me, e eu vos farei pescadores de homens."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Imediatamente, deixadas as redes, o seguiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'Tendo passado um pouco adiante dali, viu Tiago, filho de Zebedeu, e João, seu irmão, que estavam também numa barca consertando as redes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Chamou-os logo. Eles, tendo deixado na barca seu pai Zebedeu com os jornaleiros, seguiram-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Depois foram a Cafarnaum; e Jesus tendo entrado no sábado na sinagoga, ensinava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Os ouvintes ficavam admirados com a sua doutrina, porque os ensinava, como quem tem autoridade, e não como os escribas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Na sinagoga estava um homem possesso do espírito imundo, o qual começou a vociferar:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, '"Que tens tu que ver connosco, ó Jesus Nazareno? Vieste para nos perder? Sei quem és, o Santo de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'Mas Jesus o ameaçou, dizendo: "Cala-te, e sai desse homem!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Então o espírito imundo, agitando-o violentamente, e dando um grande grito, saiu dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'Ficaram todos tão admirados, que se interrogavam uns aos outros: "Que é isto? Que nova doutrina é esta? Ele manda com autoridade até aos espíritos imundos, e obedecem-lhe."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'E divulgou-se logo a sua fama por toda a terra da Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'Logo que saíram da sinagoga, foram a casa de Simão e de André, com Tiago e João.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'A sogra de Simão estava de cama com febre. Falaram-lhe logo dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'Jesus, aproximando-se e tomando-a pela mão, levantou-a. Imediatamente a deixou a febre, e ela pôs-se a servi-los.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 32, 'De tarde, sendo já sol-posto, traziam-lhe todos os enfermos e possessos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 33, 'e toda a cidade se tinha juntado diante da porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 34, 'Curou muitos que se achavam oprimidos com várias doenças, expeliu muitos demônios, e não lhes permitia dizer que o conheciam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 35, 'Levantando-se muito antes de amanhecer, saiu, e foi a um lugar solitário, e lá fazia oração. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 36, 'Simão e os seus companheiros foram procurá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 37, 'Tendo-o encontrado, disseram-lhe: "Todos te procuram."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 38, 'Ele respondeu: "Vamos para outra parte, para as aldeias vizinhas, a fim de que eu também lá pregue, pois para isso é que vim."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 39, 'E andava pregando nas sinagogas, por toda a Galileia, e expelia os demônios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 40, 'Foi ter com ele um leproso, fazendo-lhe suas súplicas, e, pondo-se de joelhos, disse-lhe: Se queres, podes limpar-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 41, 'Jesus, compadecido dele, estendeu a mão e, tocando-o, disse-lhe: "Quero, sê limpo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 42, 'Imediatamente desapareceu dele a lepra e ficou limpo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 43, 'E logo o mandou retirar, dizendo-lhe com tom severo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 44, '"Guarda-te de o dizer a alguém, mas vai, mostra-te ao sacerdote, e oferece pela purificação o que Moisés ordenou, para lhes servir de testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 45, 'Ele, porém, retirando-se começou a contar e a publicar o sucedido, de sorte que Jesus já não podia entrar descobertamente numa cidade, mas ficava fora nos lugares desertos, e de todas as partes iam ter com ele.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Passados alguns dias, entrou Jesus outra vez em Cafarnaum,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'e soube-se que ele estava em casa. Juntou-se muita gente, de modo que não se cabia, nem mesmo diante da porta. E ele pregava-lhes a palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Foram ter com ele, conduzindo um paralítico, que era transportado por quatro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Como não pudessem apresentar-lho por causa da multidão, descobriram o tecto pela parte debaixo da qual estava Jesus, e, tendo feito uma abertura, desceram o leito, em que jazia o paralítico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'Vendo Jesus a fé daqueles homens, disse ao paralítico: "Filho, são-te perdoados os teus pecados."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Estavam ali sentados alguns escribas, os quais iam discorrendo nos seus corações :'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, '"Como fala assim este homem ? Ele blasfema. Quem pode perdoar os pecados, senão só Deus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Jesus, conhecendo logo no seu espírito que eles discorriam desta maneira dentro de si, disse-lhes: Porque pensais isso nos vossos corações ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'O que é menos difícil dizer ao paralítico: Os teus pecados te são perdoados; ou dizer: Levanta-te, toma o teu leito, e anda?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Ora, para que saibais que o Filho do homem tem na terra poder de perdoar pecados...'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'eu te ordeno, disse ao paralítico: "Levanta-te, toma o teu leito, e vai para tua casa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Imediatamente ele se levantou, e, tomando o seu leito, retirou-se à vista de todos, de maneira que todos se admiraram e louvavam a Deus, dizendo: "Nunca tal vimos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'Foi outra vez para o lado do mar. Ia ter com ele todo o povo, e o ensinava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'Ao passar viu Levi, filho de Alfeu, sentado no telónio, e disse-lhe; "Segue-me." Ele, levantando-se, o seguiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Aconteceu que, estando Jesus sentado à mesa em casa dele, estavam também à mesa com Jesus e com os seus discípulos muitos publicanos e pecadores, porque havia muitos deles que também o seguiam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Os escribas e fariseus, vendo que Jesus comia com os pecadores e publicanos, diziam a seus discípulos : "Porque come e bebe o vosso Mestre com os publicanos e pecadores?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Ouvindo isto Jesus, disse-lhes: "Os sãos não têm necessidade de médico, mas os enfermos; eu não vim chamar os justos mas os pecadores."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Os discípulos de João e os fariseus jejuavam. Foram pois ter com Jesus, e disseram-lhe: "Porque jejuam os discípulos de João e os fariseus, e não jejuam os teus discípulos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Jesus respondeu-lhes: "Podem porventura jejuar os companheiros do esposo, enquanto o esposo está com eles? Todo o tempo que têm consigo o esposo, não podem jejuar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Mas virão dias em que lhes será tirado o esposo, e então nesses dias jejuarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Ninguém cose um remendo de pano cru num vestido velho; doutra sorte o remendo novo leva parte do velho, e torna-se maior o rasgão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Ninguém lança vinho novo em odres velhos; doutra sorte o vinho fará arrebentar os odres, e entornar-se-á o vinho, e perder-se-ão os odres; mas para vinho novo, odres novos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'Sucedeu que, caminhando o Senhor em dia de sábado, por entre campos de trigo, os seus discípulos, enquanto caminhavam, começaram a colher espigas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'Os fariseus diziam-lhe: "Como é que fazem ao sábado o que não é lícito?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'Ele respondeu-lhes: "Nunca lestes o que fez David, quando se encontrou em necessidade, e teve fome, ele e os que com ele estavam?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 26, 'Como entrou na casa de Deus, sendo sumo sacerdote Abiatar, e comeu os pães da proposição, dos quais não é lícito comer, senão aos sacerdotes, e deu aos que com ele estavam?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 27, 'E acrescentou: "O sábado foi feito para o homem, e não o homem para o sábado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 28, 'Por isso o Filho do homem é senhor também do sábado." (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Outra vez Jesus entrou na sinagoga, e encontrava-se lá um homem, que tinha uma das mãos seca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Observavam-no a ver se curaria em dia de sábado, para o acusarem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'Jesus disse ao homem, que tinha a mão seca: "Vem aqui para o meio."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'Depois disse-lhes: "É lícito em dia de sábado fazer bem ou mal? Salvar a vida a uma pessoa ou tirá-la?" Eles, porém, calaram-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Olhando-os em roda com indignação, contristado da cegueira de seus corações, disse ao homem: "Estende a tua mão." Ele a estendeu, e foi-lhe restabelecida a mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'Mas os fariseus, retirando-se, entraram logo em conselho contra ele com os herodianos, para ver como o haviam de perder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Jesus retirou-se com os seus discípulos para a banda do mar, e seguiu-o uma grande multidão de povo da Galileia, da Judeia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'de Jerusalém, da Idumeia, da Transjordânia e das vizinhanças de Tiro e de Sidónia, tendo ouvido as coisas que fazia, foram também em grande multidão ter com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Mandou aos seus discípulos que lhe aprontassem uma barca, para que a multidão o não atropelasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'Porque, como curava muitos, todos os que padeciam algum mal arrojavam-se sobre ele para o tocarem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'E os espíritos imundos, quando o viam, prostravam-se diante dele, e gritavam :'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, '"Tu és o Filho de Deus." Mas ele ordenava-lhes com severidade que o não manifestassem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Tendo subido a um monte, chamou a si os que quis. Aproximaram-se dele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'e destinou doze, para que andassem com ele, e para os enviar a pregar'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'com poder de expelir os demônios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'Escolheu pois doze: Simão, a quem pós o nome de Pedro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais pôs o nome de Boanerges, que quer dizer filhos do trovão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'André, Filipe, Bartolomeu, Mateus, Tomé, Tiago, filho de Alfeu, Tadeu, Simão o Cananeu'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'e Judas Iscariotes, que o entregou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'Depois, foi para casa e concorreu de novo tanta gente, que nem mesmo podiam tomar alimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Quando os seus parentes ouviram isto, foram para o prender; porque diziam: "Está louco."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'Os escribas, que tinham descido de Jerusalém, diziam : "Está possesso de Belzebu, e em virtude do príncipe dos demônios é que expele os demônios."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Jesus tendo-os chamado, dizia-lhes em parábolas: "Como pode Satanás expelir Satanás?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'Se um reino está dividido contra si mesmo, um tal reino não pode subsistir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'E se uma casa está dividida contra si mesma, tal casa não pode ficar de pé,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'Se pois Satanás se levantar contra si mesmo, o seu reino está dividido, e não poderá subsistir, antes está para acabar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'Ninguém pode entrar na casa do forte, a roubar os seus móveis, se primeiro não prende o forte. Então saqueará a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 28, 'Na verdade vos digo que serão perdoados aos filhos dos homens todos os pecados e as blasfêmias que proferirem;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 29, 'porém, o que blasfemar contra o Espírito Santo, jamais terá perdão; mas será réu de eterno pecado." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 30, 'Jesus falou assim por terem dito : "Está possesso do espírito imundo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 31, 'Chegaram sua mãe e seus irmãos, os quais, estando fora, o mandaram chamar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 32, 'Estava sentada à roda dele muita gente. Disseram-lhe: "Eis que tua mãe e teus irmãos estão lá fora e procuram-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 33, 'Ele, respondeu-lhes: "Quem é minha mãe e quem são meus irmãos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 34, 'E, olhando para os que estavam sentados à roda de si, disse: "Eis minha mãe e meus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 35, 'Porque o que fizer a vontade de Deus, esse é meu irmão, minha irmã, e minha mãe."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Começou de novo a ensinar à beira do mar; e juntou-se à roda dele tão grande multidão que teve de subir para uma barca e sentar-se dentro dela no mar, enquanto que toda a multidão estava em terra na praia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'E ensinava-lhes muitas coisas por meio de parábolas. Dizia-lhes segundo o seu meio de ensinar :'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, '"Ouvi: Eis saiu o semeador a semear.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Enquanto semeava, uma parte da semente caiu ao longo do caminho, e vieram as aves do céu, e comeram-na.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Outra parte caiu sobre pedregulho, onde tinha pouca terra; e nasceu logo, porque não havia profundidade de terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'mas, quando saiu o sol, foi crestada pelo calor, e, como não tinha raiz, secou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Outra parte caiu entre espinhos; e cresceram os espinhos, e a sufocaram, e não deu fruto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Outra caiu em boa terra; e deu fruto que vingou, e cresceu, e um grão deu trinta, outro sessenta, e outro cem ."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'E acrescentava; "Quem tem ouvidos para ouvir, ouça."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'Quando se encontrou só, os doze, que estavam com ele, interrogaram-no sobre a parábola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'Disse-lhes; "A vós é concedido conhecer o mistério do reino de Deus; porém, aos que são de fora, tudo se lhes propõe em parábolas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'para que, olhando, não vejam, ouvindo, não entendam, de sorte que não se convertam, e lhes sejam perdoados os pecados." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'E acrescentou: "Não entendeis esta parábola? Então como entendereis todas as outras? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'O que o semeador semeia é a palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'Uns encontram-se ao longo do caminho onde ela é semeada; logo que a ouviram, vem Satanás tirar a palavra semeada neles. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Outros recebem a semente em terreno pedregoso; ouvem a palavra, logo a recebem com gosto;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'mas não têm raízes em si, são inconstantes; depois, levantando-se a tribulação ou a perseguição por causa da palavra, sucumbem imediatamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'Outros recebem a semente entre espinhos; ouvem a palavra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'mas as solicitudes do século, a sedução das riquezas, e os outros afetos desordenados, entrando, afogam a palavra, e ela fica infrutuosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Outros recebem a semente em boa terra; ouvem a palavra, recebem-na, e dão fruto, um a trinta, outro a sessenta, e outro a cem por um.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'Dizia-lhes mais: "Porventura traz-se a lucerna para a meter debaixo do alqueire ou debaixo do leito? Não é para ser posta sobre o candelabro? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'Porque não há coisa alguma escondida que não venha a ser manifesta, nem que seja feita para estar oculta, mas para vir a descoberto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'Se alguém tem ouvidos para ouvir, ouça. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Dizia-lhes mais: "Atendei ao que ouvis. Com a medida com que medirdes, vos medirão a vós, e ainda se vos acrescentará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'Porque ao que tem, dar-se-lhe-á ainda mais e ao que não tem, ainda o que tem, lhe será tirado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'Dizia também: "O reino de Deus é como um homem que lança a semente à terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 27, 'Dorme e se levanta, noite e dia, e a semente brota e cresce sem ele saber como. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 28, 'Porque a terra por si mesma produz, primeiramente, a erva, depois a espiga, e por último o trigo grado na espiga.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 29, 'E, quando o fruto está maduro, mete logo a fouce, porque está chegado o tempo da ceifa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 30, 'Dizia mais: "A que coisa compararemos nós o reino de Deus? Com que parábola o figuraremos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 31, 'É como um grão de mostarda que, quando se semeia na terra, é a menor de todas as sementes que há na terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 32, 'mas, depois que é semeado, cresce e torna-se maior que todas as hortaliças, e cria grandes ramos, de modo que as aves do céu podem vir pousar à sua sombra (Dn. 4, 9 e Dn. 4, 18; Ez. 17, 23 e Ez. 31, 6).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 33, 'Assim lhes propunha a palavra com muitas parábolas como estas, conforme o permitia a capacidade dos ouvintes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 34, 'Não lhes falava sem parábolas; porém, tudo explicava em particular a seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 35, 'Naquele mesmo dia, já sobre a tarde, disse-lhes: "Passemos à outra banda."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 36, 'Deixando a multidão, o levaram, assim como estava, na barca. Outras embarcações o seguiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 37, 'Então levantou-se uma grande tormenta de vento, e as ondas lançavam-se sobre a barca, de sorte que a barca se enchia de água. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 38, 'Jesus estava dormindo na popa, sobre um travesseiro. Acordaram-no, e disseram-lhe : "Mestre, não se te dá que pereçamos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 39, 'Ele levantou-se, ameaçou o vento, e disse para o mar: "Cala-te, emudece." O vento amainou, e seguiu-se uma grande bonança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 40, 'Depois disse-lhes : "Porque sois tão tímidos? Ainda não tendes fé?" Ficaram cheios de grande temor, e diziam uns para os outros: "Quem será este, que até o vento e o mar lhe obedecem?"');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Chegaram à outra banda do mar, ao território dos gerasenos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Ao sair Jesus da barca, foi logo ter com ele, saindo dos sepulcros, um homem possesso de um espírito imundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Tinha o seu domicílio nos sepulcros, e nem com cadeias o podia alguém ter preso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Tendo sido atado por muitas vezes com grilhões e com cadeias, tinha quebrado as cadeias e despedaçado os grilhões, e ninguém o podia domar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'E sempre, dia e noite, andava pelos sepulcros e pelos montes, gritando e ferindo-se com pedras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Vendo, porém, a Jesus de longe, correu e prostrou-se diante dele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'e clamou em alta voz: "Que tens tu comigo, Jesus, Filho de Deus Altíssimo? Eu te conjuro por Deus que me não atormentes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Porque Jesus dizia-lhe : "Espírito imundo sai desse homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Depois perguntou-lhe: "Que nome é o teu?" Ele respondeu: "O meu nome é Legião, porque somos muitos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'E suplicava-lhe instantemente que o não expulsasse daquele pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Andava ali pastando ao redor do monte uma grande vara de porcos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Os espíritos imundos suplicaram-lhe : "Manda-nos para os porcos, para nos metermos neles."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Jesus deu-lhes essa permissão. Então os espíritos imundos saíram e entraram nos porcos, e a vara, que era de cerca de dois mil, precipitou-se por um despinhadeiro no mar, onde se afogaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Os que andavam apascentando fugiram e foram espalhar a noticia pela cidade e pelos campos. E o povo foi ver o que tinha sucedido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Foram ter com Jesus, e viram o que tinha sido vexado do demônio sentado, vestido e são do juízo, ele, que tinha estado possesso de uma legião inteira; e tiveram medo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Os que tinham visto contaram-lhes o que tinha acontecido ao endemoninhado e aos porcos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Então começaram a rogar a Jesus que se retirasse do território deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Quando Jesus subia para a barca, começou o que fora vexado do demônio a pedir-lhe que lhe permitisse acompanhá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Mas Jesus não o permitiu, antes lhe disse: "Vai para tua casa, para os teus, e anuncia-lhes quão grandes coisas o Senhor te fez, e como teve piedade de ti."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'Ele retirou-se e começou a publicar pela Decápole quão grandes coisas lhe linha feito Jesus; e todos se admiravam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Tendo passado Jesus novamente para a outra banda na barca, concorreu a ele muita gente, e ele estava junto do mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'Chegou um dos chefes da sinagoga, chamado Jairo, o qual, vendo-o, lançou-se a seus pés,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'e suplicava-lhe com instância: "Minha filha está nas últimas; vem, impõe sobre ela a mão, para que seja salva, e viva."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Jesus foi com ele, e uma grande multidão o seguia e o apertava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Então uma mulher, que há doze anos padecia um fluxo de sangue,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 26, 'que tinha sofrido muito de muitos médicos, e tinha gastado tudo quanto possuía, sem ter sentido melhoras, antes cada vez se achava pior,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 27, 'tendo ouvido falar de Jesus, foi por detrás, entre a turba, e tocou o seu vestido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 28, 'Porque dizia: "Se eu tocar, ainda que seja só o seu vestido, ficarei curada."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 29, 'Imediatamente parou o fluxo de sangue, e sentiu no seu corpo estar curada do mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 30, 'Jesus, conhecendo logo em si mesmo a virtude que saíra dele, voltado para a multidão, disse: "Quem tocou os meus vestidos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 31, 'Os seus discípulos responderam: "Tu vês que a multidão te comprime, e perguntas: Quem me tocou?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 32, 'E Jesus olhava em roda para ver a que tinha feito isto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 33, 'Então a mulher, que sabia o que se tinha passado nela, cheia de medo, e tremendo, foi prostrar-se diante dele, e disse-lhe toda a verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 34, 'Jesus disse-lhe: "Filha, a tua fé te salvou; vai em paz, e fica curada do teu mal."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 35, 'Ainda ele falava, quando chegaram de casa do chefe da sinagoga, dizendo: "Tua filha morreu; para que incomodar mais o Mestre?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 36, 'Porém, Jesus, tendo ouvido o que eles diziam, disse ao príncipe da sinagoga: "Não temas; crê sòmente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 37, 'E não permitiu que ninguém o acompanhasse, senão Pedro, Tiago e João, irmão de Tiago.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 38, 'Chegando a casa do príncipe da sinagoga, viu Jesus o alvoroço, os que estavam chorando e fazendo grandes prantos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 39, 'Tendo entrado, disse-lhes: "Por ­que vos perturbais e chorais? A menina não está morta, mas dorme."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 40, 'E zombavam dele. Mas ele, tendo feito sair todos, tomou o pai e a mãe da menina, e os que o acompanhavam, e entrou onde a menina estava deitada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 41, 'Tomando a mão da menina, disse-Ihe : "Talitha koum, que quer dizer: Menina, eu te mando, levanta-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 42, 'Imediatamente se levantou a menina, e andava; pois tinha já doze anos. Ficaram cheios de grande espanto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 43, 'Jesus ordenou-lhes rigorosamente que ninguém o soubesse. Depois disse que dessem de comer à menina.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Tendo Jesus partido dali, foi para a sua pátria; e seguiam-no os seus discípulos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Chegando o sábado, começou a ensinar na sinagoga. Os seus numerosos ouvintes admiravam-se e diziam : "Donde vêm a este todas estas coisas que diz? Que sabedoria é esta que lhe foi dada? E como se operam tais maravilhas pelas suas mãos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Não é este o carpinteiro, filho de Maria, irmão de Tiago, de José, de Judas e de Simão? Não vivem aqui entre nós também suas irmãs?" E estavam perplexos a seu respeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Mas Jesus dizia-lhes: "Um profeta só deixa de ser honrado na sua pátria, entre os seus parentes e na sua própria casa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'E não podia fazer ali milagre algum; apenas curou alguns poucos enfermos, impondo-lhes as mãos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'E admirava-se da incredulidade deles. Depois andava ensinando pelas aldeias circunvizinhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Chamou os doze, e começou a enviá-los dois a dois, dando-lhes poder sobre os espíritos imundos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Ordenou-lhes que não tomassem nada para o caminho, senão sòmente um bastão; nem alforge, nem pão, nem dinheiro na cintura;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'mas que fossem calçados de sandálias, e não levassem duas túnicas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'E dizía-Ihes: "E m qualquer casa onde entrardes, ficai nela até sairdes daquele lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Onde vos não receberem, nem vos ouvirem, retirando-vos de lá, sacudi o pó dos vossos pés em testemunho contra eles."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Tendo partido, pregavam aos povos que fizessem penitência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Expeliam muitos demônios, ungiam com óleo muitos enfermos, e curavam-nos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Ora o rei Herodes ouviu falar de Jesus, cujo nome se tinha tornado célebre. Dizia-se: "João Batista ressuscitou de entre os mortos; é por isso que o poder de fazer milagres opera nele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Outros, porém, diziam : "É Elias." E outros diziam : "É um profeta, como um dos antigos profetas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Herodes, tendo ouvido isto, disse: "Este é aquele João, a quem eu mandei degolar, e que ressuscitou dos mortos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'Porque Herodes tinha mandado prender João, e teve-o em ferros no cárcere por causa de Herodíades, mulher de Filipe, seu irmão, com a qual tinha casado (ilicitamente),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Porque João dizia a Herodes: "Não te é lícito ter a mulher de teu irmão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Herodíades tinha-lhe rancor e queria fazê-lo morrer, porém não podia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'porque Herodes, sabendo que João era varão justo e santo, olhava-o com respeito, protegia-o, e, quando o ouvia, ficava muito perplexo, porém ouvia-o de boa vontade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Chegando um dia oportuno, Herodes, no aniversário do seu nascimento, deu um banquete aos grandes da corte, aos tribunos e aos principais da Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Tendo entrado na sala a filha da mesma Herodíades, dançou e agradou a Herodes e aos seus convivas. O rei disse à moça: "Pede-me o que quiseres e eu to darei."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'E jurou-lhe: "Tudo o que me pedires, te darei, ainda que seja metade do meu reino."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Ela, tendo saído, disse a sua mãe" "Que hei-de eu pedir?" Ela respondeu-lhe: "A cabeça de João Batista."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Tornando logo a entrar apressadamente junto do rei, fez este pedido: "Quero que imediatamente me dês num prato a cabeça de João Batista."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'O rei entristeceu-se, mas, por causa do juramento e dos convivas, não quis desgostá-la.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Imediatamente mandou um guarda com ordem de trazer a cabeça de João. Ele foi degolá-lo no cárcere,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 28, 'levou a sua cabeça num prato, deu-o à moça, e a moça a deu a sua mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 29, 'Tendo ouvido isto os seus discípulos, foram, tomaram o seu corpo, e o depuseram num sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 30, 'Tendo os Apóstolos voltado a Jesus, contaram-Ihe tudo o que tinham feito e ensinado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 31, 'Ele disse-Ihes: "Vinde aparte, a um lugar solitário, e descansai um pouco." Porque eram muitos os que iam e vinham, e nem tinham tempo para comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 32, 'Entrando pois numa barca, retiraram-se aparte, a um lugar solitário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 33, 'Porém viram-nos partir, e muitos souberam para onde iam, e concorreram lá, a pé, de todas as cidades, e chegaram primeiro que eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 34, 'Ao desembarcar, viu Jesus uma grande multidão. Teve compaixão deles, porque eram como ovelhas sem pastor, e começou a ensinar-lhes muitas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 35, 'Fazendo-se tarde, chegaram-se a eles seus discípulos, dizendo: "Este lugar é solitário e a hora é já adiantada;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 36, 'despede-os, a fim de que vão às quintas e povoados próximos e comprem alguma coisa para comer."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 37, 'Ele respondeu-lhes: "Dai-lhes vós de comer." Eles disseram: "Iremos pois com duzentos dinheiros comprar pão para lhes darmos de comer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 38, 'Jesus perguntou-lhes: "Quantos pães tendes vós? Ide ver." Depois de terem examinado, disseram-lhe: "Temos cinco, e dois peixes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 39, 'Então mandou-lhes que os fizessem recostar a todos, em grupos, sobre a relva verde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 40, 'E recostaram-se em grupos de cem e de cinquenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 41, 'Jesus, tomando os cinco pães e os dois peixes, elevando os olhos ao céu, abençoou e partiu os pães, e os deu a seus discípulos para que lhos servissem; igualmente repartiu por todos os dois peixes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 42, 'Todos comeram e ficaram saciados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 43, 'E recolheram doze cestos cheios das sobras dos pães e dos peixes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 44, 'Os que tinham comido dos pães eram cinco mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 45, 'Imediatamente Jesus obrigou seus discípulos a embarcar, para chegarem primeiro que ele à outra banda do lago, a Betsaida, enquanto despedia o povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 46, 'Depois que os despediu, retirou-se a um monte a fazer oração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 47, 'Chegada a noite, encontrava-se a barca no meio do mar, e ele só em terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 48, 'Vendo-os cansados de remar, (porque o vento lhes era contrário), cerca da quarta vigília da noite foi ter com eles, andando sobre o mar; e fez menção de passar adiante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 49, 'Quando eles o viram caminhar sobre o mar, julgaram que era um fantasma e gritaram'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 50, 'porque todos o viram e se assustaram. Mas ele falou-lhes logo e disse: "Tende confiança, sou eu, não temais."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 51, 'Subiu em seguida para a barca a ir ter com eles, e o vento cessou. Ficaram extremamente estupefactos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 52, 'pois não tinham dado conta do que se tinha passado com os pães; o seu coração estava obcecado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 53, 'Tendo passado à outra banda, foram ao país de Genesaré, e lá aportaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 54, 'Tendo desembarcado, logo o conheceram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 55, 'e, correndo por todo aquele país, começaram a trazer-lhe todos os doentes em leitos, onde sabiam que ele estava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 56, 'Em qualquer lugar a que chegava, nas aldeias, nas cidades ou nas herdades, punham os enfermos no meio das praças, e pediam-lhe que os deixasse tocar ao menos a orla do seu vestido. E todos os que o tocavam ficavam sãos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Reuniram-se em volta de Jesus os fariseus e alguns dos escribas, vindos de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Tendo visto alguns dos seus discípulos comer o pão com as mãos impuras, isto é, por lavar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, '(porque os fariseus e todos os Judeus, em observância da tradição dos antigos, não comem sem lavar as mãos cuidadosamente;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'e, quando vêm da praça pública, não comem sem se purificar; e praticam muitas outras observâncias tradicionais, como lavar os copos, os jarros, os vasos de metal, e os leitos),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'os fariseus e os escrivas interrogaram-no : "Porque não andam os teus discípulos segundo a tradição dos antigos, mas comem o pão sem lavar as mãos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Ele respondeu-lhes: "Com razão Isaías profetizou de vós, hipócritas, quando escreveu (Is. 29, 13): Este povo honra-me com os lábios, mas o seu coração está longe de mim'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'É vão o culto que me prestam, ensinando doutrinas que são preceitos humanos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Pondo de lado o mandamento de Deus, observais cuidadosamente a tradição dos homens."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Disse-lhes mais: "Vós bem fazeis por destruir o mandamento de Deus, para manter a vossa tradição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'Porque Moisés disse: Honra teu pai e tua mãe. E todo o que amaldiçoar seu pai ou sua mãe, seja punido de morte (Ex. 20, 12 ; Dt. 5, 16 ; Ex. 21, 17).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'Porém vós dizeis; Se alguém disser a seu pai ou a sua mãe: É oferta a Deus qualquer coisa minha que te possa ser útil; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'e não lhe deixais fazer nada em favor de seu pai ou de sua mãe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'anulando assim a palavra de Deus por uma tradição, que tendes transmitido de uns aos outros. E fazeis muitas coisas semelhantes a esta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Convocando novamente o povo, dizia-lhe : "Ouvi-me todos, e entendei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Não há coisa fora do homem que, entrando nele, o possa manchar, mas as que saem do homem, essas são as que tornam o homem impuro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Se alguém tem ouvidos para ouvir, ouça."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Tendo entrado em casa, deixada a multidão, os seus discípulos interrogaram-no sobre esta parábola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Ele respondeu-lhes: "Também vós sois ignorantes? Não compreendeis que tudo o que, de fora, entra no homem, não o pode contaminar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'porque não entra no seu coração, mas vai ter ao ventre, e lança-se num lugar escuso ?" Com isto declarava puros todos os alimentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'E acrescentava: "O que sai do homem, é que contamina o homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Porque do interior, do coração do homem é que procedem os maus pensamentos, os furtos, as fornicações, os homicídios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'os adultérios, as avarezas, as perversidades, as fraudes, as libertinagens, a inveja, a maledicência, a soberba, a loucura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Todos estes males procedem de dentro, e contaminam o homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Partindo dali, foi Jesus para o território de Tiro e de Sidónia. Tendo entrado numa casa, não queria que ninguém o soubesse, mas não pôde ocultar-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Porque uma mulher, cuja filha estava possessa do espirito imundo, logo que ouviu falar dele, foi lançar-se a seus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'Era uma mulher gentia, siro-fenícia de nação. Suplicava-lhe que expelisse o demônio de sua filha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'Jesus disse-lhe: "Deixa que primeiro sejam fartos os filhos, porque não é bem tomar o pão dos filhos e lançá-lo aos cães."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'Mas ela respondeu-lhe : "Assim é, Senhor, mas também os cachorrinhos comem, debaixo da mesa, das migalhas que caem dos meninos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'Ele disse-lhe : "Por esta palavra que disseste, vai, o demônio saiu de tua filha."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 30, 'Tendo voltado para sua casa, encontrou a menina deitada sobre o leito, tendo o demônio saindo dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 31, 'Jesus, deixando o território de Tiro, foi novamente por Sidónia ao mar da Galileia, atravessando o território da Decápole.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 32, 'Trouxeram-lhe um surdo-mudo, e suplicavam-lhe que lhe impusesse a mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 33, 'Então Jesus, tomando-o aparte dentre a multidão, meteu-lhe os dedos nos ouvidos, e tocou com saliva a sua língua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 34, 'Depois, levantando os olhos ao céu, deu um suspiro, e disse-lhe: "Ephphata", que quer dizer "abre-te". (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 35, 'Imediatamente se lhe abriram os ouvidos, se lhe soltou a prisão da língua, e falava claramente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 36, 'Ordenou-lhes que a ninguém o dissessem. Porém, quanto mais lho proibia, mais o publicavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 37, 'E admiravam-se, sobremaneira, dizendo: "Tudo tem feito bem! Faz ouvir os surdos, e falar os mudos!');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Naqueles dias, havendo novamente grande multidão, e, não tendo que comer, chamados os discípulos, disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, '"Tenho compaixão deste povo, porque há já três dias que não se afastam de mim, e não têm que comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Se os despedir em jejum para suas casas, desfalecerão no caminho e alguns deles vieram de longe."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'Os discípulos responderam-lhe: "Como poderá alguém saciá-los de pão aqui num deserto?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Jesus perguntou-lhes: "Quantos pães tendes?" Responderam: "Sete."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Então ordenou ao povo que se recostasse sobre a terra. Depois, tomando os sete pães, deu graças, partiu-os e deu a seus discípulos, para que os distribuíssem ; e eles os distribuíram pelo povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Tinham também uns poucos de peixinhos. Ele os abençoou, e mandou que fossem distribuídos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Comeram, ficaram saciados, e, dos pedaços que sobejaram, levantaram sete cestos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Ora os que comeram eram cerca de quatro mil. Em seguida Jesus despediu-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Entrando logo na barca com seus discipulos, passou ao território de Dalmanuta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Apareceram os fariseus, e começaram a disputar com ele, pedindo-lhe, para o tentarem, um sinal do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Porém Jesus, arrancando do coração um suspiro, disse: "Porque pede esta geração um sinal? Em verdade vos digo que a esta geração não será dado sinal algum."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Depois, deixando-os, entrou novamente na barca, e passou à outra banda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'Ora os discípulos esqueceram-se de tomar pães; e não tinham consigo na barca, senão um único.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Jesus advertia-os, dizendo: "Evitai com cuidado o fermento dos fariseus, e o fermento de Herodes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'E eles discorriam entre si : "É que nós não temos pão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Conhecendo isto Jesus, disse-lhes: "Porque estais vós a discutir que não tendes pão? Ainda não refletiste nem entendestes? Ainda tendes o vosso coração obcecado ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Tendo olhos, não vedes, e tendo ouvidos, não ouvis? Já não vos recordais?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Quando dividi cinco pães por cinco mil homens, quantos cestos levantastes cheios de pedaços?" Eles responderam: "Doze."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, '"E quando dividi sete pães entre quatro mil, quantos cestos levantastes de pedaços?" Responderam : "Sete."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'E dizia-lhes: "Como é que não entendeis ainda?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Chegaram a Betsaida. Trouxeram-lhe um cego, e suplicavam-lhe que o tocasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 23, 'Tomando o cego pela mão, conduziu-o fora da aldeia, pós-lhe saliva sobre os olhos, e, impondo-lhe as suas mãos, perguntou-lhe: "Vês alguma coisa?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 24, 'Ele, levantando os olhos, disse : "Vejo os homens que me parecem árvores ­que andam."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 25, 'Depois Jesus impôs-lhe novamente as mãos sobre os olhos, e começou a ver claramente; ficou curado e distinguia tudo, nitidamente, de longe. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 26, 'Então Jesus mandou-o para casa, dizendo: "Não entres na aldeia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 27, 'Saiu Jesus com os seus discipulos pelas aldeias de Cesareia de Filipe. Pelo caminho, interrogou os seus discípulos: "Quem dizem os homens que eu sou?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 28, 'Eles responderam-lhe: "Uns dizem que João Batista, outros que Elias, e outros que algum dos profetas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 29, 'Então perguntou-lhes: "E vós quem dizeis que eu sou? Pedro respondeu: "Tu és o Messias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 30, 'Então Jesus ordenou-lhes severamente que a ninguém dissessem isto dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 31, 'E começou a declarar-lhes que era necessário que o Filho do homem padecesse muito, que fosse rejeitado pelos anciães, pelos príncipes dos sacerdotes, e pelos escribas, que fosse morto, e que ressuscitasse depois de três dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 32, 'E falava destas coisas claramente. Pedro, tomando-o de parte, começou a repreendê-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 33, 'Mas Jesus, voltando-se e olhando para seus discípulos, repreendeu Pedro, dizendo : "Retira-te daqui Satanás, que não tens gosto pelas coisas de Deus, mas sim pelas dos homens." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 34, 'Depois, chamando a si o povo com seus discípulos, disse-lhes: "Se alguém me quer seguir, negue-se a si mesmo, tome a sua cruz, e siga-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 35, 'Porque o que quiser salvar a sua vida, a perderá; mas o que perder a sua vida por amor de mim e do Evangelho, a salvará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 36, 'Pois que aproveitará ao homem ganhar o mundo inteiro e perder a sua alma?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 37, 'Ou que dará o homem em troco da sua alma?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 38, 'No meio desta geração adúltera e pecadora, quem se envergonhar de mim e das minhas palavras, também o Filho do homem se envergonhará dele, quando vier na glória de seu Pai com os santos anjos."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'E dizia-lhes: "Em verdade vos digo que, dos que aqui se encontram, alguns não morrerão sem terem visto antes o reino de Deus vir com poder." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Seis dias depois, tomou Jesus consigo Pedro, Tiago e João, e conduziu-os sós, aparte, a um alto monte, e transfigurou-se diante deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Os seus vestidos tornaram-se resplandecentes, em extremo brancos, como nenhum lavandeiro sobre a terra os poderia tornar tão brancos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Depois apareceu-lhes Elias com Moisés, que estavam falando com Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'Pedro, tomando a palavra, disse a Jesus: "Mestre, é bom que estejamos aqui: façamos três tendas, uma para ti, outra para Moisés, outra para Elias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Porque não sabia o que dizia, pois estavam atônitos de medo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'E formou-se uma nuvem que os cobriu com a sua sombra, e saiu uma voz da nuvem, que dizia: "Este é o meu Filho caríssimo, ouvi-o."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Olhando logo em roda, não viram mais ninguém com eles senão Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Ao descerem do monte, ordenou-lhes que a ninguém contassem o que tinham visto, senão quando o Filho do homem tivesse ressuscitado dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Observaram esta ordem, investigando entre si o que queria dizer: "Quando tiver ressuscitado dos mortos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Interrogaram-no, dizendo: "Porque dizem os escribas que Elias deve vir primeiro?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Jesus respondeu-lhes: "Elias efetivamente há-de vir primeiro e pôr tudo em ordem. Como está escrito acerca do Filho do homem, que terá de sofrer muito e ser desprezado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'Mas digo-vos que Elias já veio, e fizeram dele quanto quiseram, como está escrito dele." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Chegando junto dos seus discípulos, viu uma grande multidão em volta deles, e os escribas disputando com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'E logo toda aquela multidão surpreendida ao ver Jesus, correu para o saudar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Perguntou-lhes: "Que estais disputando entre vós?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Um de entre a multidão respondeu-lhe: "Mestre, eu trouxe-te meu filho que está possesso de um espirito mudo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'o qual, onde quer que se apodere dele, o lança por terra, e o menino espuma, range com os dentes, e fica entorpecido. Roguei a teus discípulos que o expelissem, e não puderam."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Jesus respondeu-lhes: "Ó geração incrédula! Até quando hei-de estar convosco? Até quando vos hei-de suportar? Trazei-mo cá."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Levaram-lho. Tendo visto Jesus, imediatamente o espírito o agitou com violência, e, caído por terra, revolvia-se espumando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'Jesus perguntou ao pai dele: "Há quanto tempo lhe sucede isto?" Ele respondeu: "Desde a infância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'O demônio tem-no lançado muitas vezes no fogo e na água, para o matar; porém tu, se podes alguma coisa, vale-nos, tem compaixão de nós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'Jesus disse-lhe: "Se podes... tudo é possível ao que crê." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Imediatamente o pai do menino exclamou; "Eu creio! Auxilia a minha falta de fé."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'Jesus, vendo aumentar a multidão, ameaçou o espírito imundo, dizendo-lhe : "Espírito mudo e surdo, eu te mando; sai desse menino, e não tornes a entrar nele!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'Então, dando gritos e agitando-o com violência, saiu dele, e o menino ficou como morto, de sorte que muitos diziam: "Está morto."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'Porém Jesus, tomando-o pela mão, levantou-o, e ele ergueu-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 28, 'Depois que entrou em casa, seus discípulos perguntaram-lhe particularmente: "Porque o não pudemos nós expelir?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 29, 'Respondeu-lhes: "Esta casta de demônios não se pode expelir, senão mediante a oração e o jejum."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 30, 'Tendo partido dali, atravessaram a Galileia; e Jesus não queria que se soubesse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 31, 'Ia instruindo os seus discípulos, e dizia-lhes: "O Filho do homem vai ser entregue às mãos dos homens, e lhe darão a morte, e ressuscitará ao terceiro dia, depois da sua morte."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 32, 'Mas eles não compreendiam estas palavras, e temiam interrogá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 33, 'Nisto chegaram a Cafarnaum. Quando estavam em casa, Jesus perguntou-lhes: "De que vínheis vós discutindo pelo caminho?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 34, 'Eles, porém, calaram-se, porque no caminho tinham discutido entre si qual deles era o maior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 35, 'Então, sentando-se, chamou os doze, e disse-lhes: "Se alguém quer ser o primeiro, será o último de todos e o servo de todos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 36, 'Em seguida, tomando um menino, pô-lo no meio deles, e, depois de o abraçar, disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 37, '"Todo o que receber um destes meninos em meu nome, a mim recebe, e todo o que me receber a mim, não me recebe a mim, mas aquele que me enviou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 38, 'João disse-lhe: "Mestre, vimos um, que não anda connosco, expelir os demônios em teu nome, e nós lho proibimos, porque não nos segue."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 39, 'Jesus, porém, respondeu : "Não lho proibais, porque não há ninguém que faça um milagre em meu nome e que possa logo dizer mal de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 40, 'Porque quem não é contra nós, está connosco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 41, 'Quem vos der um copo de água, por que sois de Cristo, em verdade vos digo que não perderá a sua recompensa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 42, 'Quem escandalizar um destes pequeninos que, creem em mim, melhor lhe fora que lhe atassem à roda do pescoço a mó que um asno faz girar, e que o lançassem ao mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 43, 'Se a tua mão é para ti ocasião de queda, corta-a; melhor te é entrar na vida eterna manco, do que, tendo duas mãos, ir para a geena, para o fogo inextinguível,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 44, 'onde o seu verme não morre, e o fogo não se apaga (Is. 66, 24). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 45, 'Se o teu pé é para ti ocasião de queda, corta-o; melhor te é entrar na vida eterna coxo, do que, tendo dois pés, ser lançado na geena,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 46, 'onde o seu verme não morre, e o fogo não se apaga (Is. 66, 24).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 47, 'Se o teu olho é para ti ocasião de queda, lança-o fora; melhor te é entrar no reino de Deus sem um olho, do que, tendo dois, ser lançado na geena,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 48, 'onde o seu verme não morre, e o fogo não se apaga (Is. 66, 24).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 49, 'Todo o homem será salgado pelo fogo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 50, 'O sal é uma coisa boa, porém, se se tornar insípido, com que haveis de lhe dar o sabor? Tende sal em vós, e tende paz uns com os outros."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Saindo dali, foi Jesus para o território da Judeia, e alem do Jordão. Novamente as multidões se juntaram em volta dele, e de novo as ensinava, segundo o seu costume,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Aproximando-se os fariseus, perguntavam-lhe para o tentarem: "É lícito ao marido repudiar sua mulher?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'Ele respondeu-lhes: "Que vos mandou Moisés?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Eles responderam: "Moisés permitiu escrever libelo de divórcio, e separar-se dela (Dt. 24, 1)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Jesus disse-lhes: "Por causa da dureza de vosso coração é que ele vos deu essa lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Porém, no princípio da criação. Deus fê-los homem e mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Por isso deixará o homem seu pai e sua mãe, e se juntará a sua mulher;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'e os dois serão uma só carne (Gn. 2, 24). Assim não mais são dois, mas uma só carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Portanto não separe o homem o que Deus juntou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'Em casa os seus discípulos interrogaram-no novamente sobre o mesmo assunto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Ele disse-lhes: "Qualquer que repudiar sua mulher e se casar com outra, comete adultério contra a primeira;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'e se a mulher repudiar seu marido e se casar com outro, comete adultério."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Apresentavam-lhe uns meninos para que os tocasse, mas os discípulos ameaçavam os que lhos apresentavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Vendo isto Jesus, ficou muito desgostoso, e disse-lhes: "Deixai vir a mim os meninos, não os embaraceis, porque destes tais é o reino de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'Em verdade vos digo: "Todo o que não receber o reino de Deus como um menino, não entrará nele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Depois, abraçou-os, e, impondo-lhes as mãos, os abençoava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Tendo saído para se pôr a caminho, veio um homem correndo, e, ajoelhando-se diante dele, perguntou-lhe : "Bom Mestre, que devo fazer para alcançar a vida eterna?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Jesus disse-lhe: "Porque, me chamas bom? Ninguém é bom senão Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'Tu conheces os mandamentos: Não mates, não cometas adultério, não furtes, não digas falso testemunho, não cometas fraudes, honra teu pai e tua mãe (Ex. 20, 13-16); Dt. 5, 17-20)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Ele respondeu: "Mestre, todas estas coisas tenho observado desde a minha mocidade."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Jesus, pondo nele os olhos, mostrou-lhe afeto, e disse-lhe: "Uma coisa te falta; vai, vende quanto tens, dá-o aos pobres, e terás um tesouro no céu; depois vem e segue-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'Mas ele, entristecido por esta palavra, retirou-se desgostoso, porque tinha muitos bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'Jesus, olhando em roda, disse a seus discípulos: "Quanto é difícil que entrem no reino de Deus os que têm riquezas!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Os discípulos assombravam-se das suas palavras. Mas Jesus de novo lhes disse: "Meus filhos, quanto é difícil entrarem no reino de Deus os que confiam nas riquezas!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'Mais fácil é passar um camelo pelo fundo de uma agulha, do que um rico entrar no reino de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Eles, de cada vez mais admirados, diziam uns para os outros: "Quem pode logo salvar-se?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'Jesus, olhando para eles, disse: "Para os homens isto é impossível, mas não para Deus, porque a Deus tudo é possível."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'Pedro começou a dizer-lhe: "Eis que deixámos tudo, e te seguimos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'Jesus respondeu : "Na verdade vos digo : Ninguém há que tenha deixado a casa, os irmãos, as irmãs, o pai, a mãe, os filhos, ou as terras, por causa de mim e do Evangelho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'que não receba o cêntuplo, mesmo nesta vida, em casas, irmãos, irmãs, mães, filhos e terras, mesmo no meio das perseguições, e no século futuro a vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'Porém muitos dos primeiros serão os últimos, e os últimos serão os primeiros." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'Iam em viagem para subir a Jerusalém; Jesus ia adiante deles. E iam perturbados, e seguiam-no com medo. Tomando novamente de parte os doze, começou a dizer-lhes o que tinha de lhe acontecer:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 33, '"Eis que subimos a Jerusalém, e o Filho do homem será entregue aos príncipes dos sacerdotes, e aos escribas; eles o condenarão à morte, e o entregarão aos gentios;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 34, 'o escarnecerão, lhe cuspirão, o açoutarão, e lhe tirarão a vida. Mas, ao terceiro dia, ressuscitará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 35, 'Então aproximaram-se dele Tiago e João, filhos de Zebedeu, dizendo : "Mestre, queremos que nos concedas o que te vamos pedir."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 36, 'Ele disse-lhes: "Que quereis vós que eu vos conceda?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 37, 'Eles responderam: "Concede-nos que, na tua glória, um de nós se sente à tua direita e outro à tua esquerda."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 38, 'Mas Jesus disse-lhes: "Não sabeis o que pedis. Podeis vós beber o cálice que eu vou beber, ou ser batizados no batismo em que eu vou ser batizado?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 39, 'Eles disseram-lhe : "Podemos." Jesus disse-lhes: "Efetivamente haveis de beber o cálice que eu vou beber, e haveis de ser batizados no batismo em que eu vou ser batizado; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 40, 'mas, quanto a estardes sentados à minha direita ou à minha esquerda, não pertence a mim o conceder-vo-lo, mas é para aqueles, para quem está preparado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 41, 'Ouvindo isto os dez, começaram a indignar-se contra Tiago e João.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 42, 'Mas Jesus, chamando-os, disse-Ihes: "Vós sabeis que aqueles que são reconhecidos como chefes das nações as dominam, e que os seus príncipes têm poder sobre elas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 43, 'Porém entre vós não deve ser assim, mas o que quiser ser o maior, será o vosso servo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 44, 'e o que entre vós quiser ser o primeiro, será servo de todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 45, 'Porque também o Filho do homem não veio para ser servido, mas para servir, e para dar a sua vida para redenção de muitos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 46, 'Chegaram a Jericó. Ao sair de Jericó, ele, os seus discípulos e grande multidão, Bartimeu, mendigo cego, filho de Timeu, estava sentado junto ao caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 47, 'Quando ouviu dizer que era Jesus Nazareno, começou a gritar, e a dizer: "Jesus, Filho de David, tem piedade de mim!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 48, 'Muitos ameaçavam-no para que se calasse. Mas ele cada vez gritava mais forte: "Filho de David, tem piedade de mim!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 49, 'Jesus, parando, disse: "Chamai-o." Chamaram o cego, dizendo-lhe: "Tem confiança, levanta-te, ele chama-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 50, 'Ele deitando fora de si a capa, levantou-se de um salto, e foi ter com Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 51, 'Tomando Jesus a palavra, disse-lhe: "Que queres que eu te faça?" O cego respondeu: ''Rabbanni faz que eu recupere a vista."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 52, 'Então Jesus disse-lhe: "Vai, a tua fé te salvou." No mesmo instante recuperou a vista, e o seguia pelo caminho.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Quando se iam aproximando de Jerusalém, nas proximidades de Betfagé e de Betânia, perto do monte das Oliveiras, enviou dois dos seus discípulos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'e disse-lhes: "Ide à aldeia, que está defronte de vós. Logo que entrardes nela, encontrareis preso um jumentinho, em que ainda não montou homem algum; soltai-o e trazei-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Se alguém vos disser: Porque fazeis isso? Dizei-lhe: O Senhor tem necessidade dele; e logo o deixará trazer."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Indo eles, encontraram o jumentinho preso fora da porta numa encruzilhada; e desprenderam-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Alguns dos que estavam ali disseram-lhes: "Que fazeis, desprendendo o jumentinho?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Eles responderam-lhes como Jesus lhes tinha mandado, e deixaram-lho levar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Levaram o jumentinho a Jesus, puseram sobre ele os seus mantos, e Jesus montou em cima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Muitos estenderam os seus mantos pelo caminho, outros cortavam ramos das árvores nos campos e juncavam com eles a estrada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Os que iam adiante, e os que seguiam atrás, clamavam, dizendo: "Hosana! Bendito o que vem em nome do Senhor!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Bendito o reino que vem do nosso pai David! Hosana no mais alto dos céus!" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Entrou em Jerusalém no templo, e. tendo observado tudo, como fosse já tarde, foi para Betânia com os doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Ao outro dia, depois que saíram de Betânia, teve fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Vendo ao longe uma figueira que tinha folhas, foi lá ver se encontrava nela algum fruto. Aproximando-se, nada encontrou senão folhas, porque não era tempo de figos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Então disse à figueira: "Nunca jamais coma alguém fruto de ti." Ouviram-no os seus discípulos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Chegaram a Jerusalém. Tendo entrado no templo, começou a lançar fora os que vendiam e compravam no templo, e derribou as mesas dos banqueiros e as cadeiras dos que vendiam pombas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'E não consentia que alguém transportasse qualquer objeto pelo templo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'e os ensinava, dizendo: "Porventura não está escrito: A minha casa será chamada casa de oração para todas as gentes? (Is. 56, 7). Mas vós fizestes dela um covil de ladrões (Je. 7, 11)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Ouvindo isto os príncipes dos sacerdotes e os escribas, procuravam o modo de o perder; porque o temiam, visto todo o povo admirar a sua doutrina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'Quando se fez tarde, saíram da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'No outro dia pela manhã, ao passarem, viram a figueira seca até às raízes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Então Pedro, recordando-se, disse-lhe: "Olha, Mestre, como se secou a figueira que amaldiçoaste."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Jesus, respondendo, disse-lhes: "Tende fé em Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Em verdade vos digo que todo o que disser a este monte: Tira-te daí, e lança-te no mar, e não hesitar no seu coração, mas tiver fé de que tudo o que disser seja feito, lhe será feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Por isso vos digo: Tudo o que pedirdes na oração, crede que o haveis de conseguir, e que o obtereis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Quando estiverdes orando, se tendes alguma coisa contra alguém, perdoai-lhe, para que também vosso Pai, que está nos céus, vos perdoe os vossos pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'Porque, se vós não perdoardes, também o vosso Pai, que está nos céus, vos não perdoará os vossos pecados." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Voltaram a Jerusalém. E, andando Jesus pelo templo, aproximaram-se dele os príncipes dos sacerdotes, os escribas e os anciães,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'e disseram-lhe: "Com que autoridade fazes tu estas coisas? E quem te deu o direito de as fazer ?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'Jesus disse-lhes: "Eu também vos farei uma pergunta; respondei-me a ela primeiro, e eu vos direi depois com que autoridade faço estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'O batismo de João era do céu ou dos homens ? Respondei-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'Mas eles discorriam entre si: Se respondermos que era do céu, ele dirá: Por que razão logo não crestes nele?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Responderemos que era dos homens?... Temiam o povo, porque todos tinham a João por um verdadeiro profeta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 33, 'Então responderam a Jesus : "Não sabemos." E Jesus disse-lhes: "Pois nem eu tão pouco vos direi com que autoridade faço estas coisas."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'E começou a falar-lhes por parábolas : "Um homem plantou uma vinha, cercou-a com uma sebe, cavou nela um lagar, edificou uma torre (Is. 5, 1-2), e arrendou-a a uns vinhateiros, e ausentou-se daquele país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Chegado o tempo, enviou aos vinhateiros um servo para receber deles a sua parte dos frutos da vinha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Mas eles, apanhando-o, bateram-lhe, e remeteram-no com as mãos vazias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Enviou-lhes de novo outro servo, e também a este o feriram na cabeça, e o carregaram de afrontas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Enviou de novo outro, e mataram-no. Assim fizeram a muitos outros, dos quais bateram nuns, e mataram outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Tendo ainda um filho querido, também lho enviou por último, dizendo: Terão respeito a meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Porém aqueles vinhateiros disseram uns para os outros: Este é o herdeiro, vinde, matemo-lo, e será nossa a herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Pegaram nele, mataram-no, e lançaram-no fora da vinha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Que fará pois o senhor da vinha? Virá, exterminará os vinhateiros, e dará a vinha a outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Vós nunca leste este lugar da Escritura: A pedra que fora rejeitada pelos que edificavam, tornou-se cabeça do ângulo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Pelo Senhor foi feito isto, e é coisa maravilhosa aos nossos olhos (Ps. 117, 22-23)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'Procuravam apoderar-se dele, mas temeram o povo. Tinham compreendido bem que dissera esta parábola contra eles. E, deixando-o, retiraram-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Enviaram-lhe alguns dos fariseus e dos herodianos, para que o apanhassem em alguma palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Chegando eles, disseram-lhe: "Mestre, sabemos que és verdadeiro, que não atendes a respeitos humanos; porque não consideras o exterior dos homens, mas ensinas o caminho de Deus, segundo a verdade: É lícito pagar o tributo a César, ou não? Devemos pagar ou não?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'Jesus, conhecendo a sua perfídia, disse-lhes: "Porque me tentais? Trazei-me um dinheiro para o ver."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Eles lho trouxeram. Então disse-lhes: "De quem é esta imagem e inscrição?" Responderam-lhe: "De César."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Então Jesus disse-lhes: "Dai, pois, o que é de César a César, e o que é de Deus a Deus." E admiravam-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Foram ter com ele os saduceus, que negam a ressurreição, e interrogaram-no, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, '"Mestre, Moisés deixou-nos escrito que, se morrer o irmão de algum e deixar a mulher sem filhos, seu irmão tome a mulher dele e dê descendência a seu irmão (Dt. 25, 5-6).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'Ora havia sete irmãos. O primeiro tomou mulher, e morreu sem deixar filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'O segundo tomou-a, e morreu também sem deixar filhos. Da mesma sorte o terceiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'Nenhum dos sete deixou filhos. Depois deles todos, morreu também a mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'Na ressurreição, pois, quando tornarem a viver, de qual deles será a mulher? Porque os sete a tiveram por mulher."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Jesus respondeu-lhes: "Não estais vós em erro, porque não compreendeis as Escrituras, nem o poder de Deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'Quando ressuscitarem de entre os mortos, nem os homens tomarão mulheres, nem as mulheres homens, mas todos serão como os anjos no céu. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'Relativamente à ressurreição dos mortos, não tendes lido no livro de Moisés, como Deus lhe falou sobre a sarça, dizendo: Eu sou o Deus de Abraão, o Deus de Isaac, o Deus de Jacob? (Ex. 3, 6). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'Ele não é Deus dos mortos, mas dos vivos. Logo vós estais num grande erro."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'Então aproximou-se um dos escribas, que os tinha ouvido discutir. Vendo que Jesus lhes tinha respondido bem, perguntou-lhe: "Qual é o primeiro de todos os mandamentos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 29, 'Jesus respondeu-lhe: "O primeiro de todos os mandamentos é este: Ouve, Israel! O Senhor nosso Deus é o único Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 30, 'Amarás o Senhor teu Deus com todo o teu coração, com toda a tua alma, com todo o teu entendimento, e com todas as tuas forças (Dt. 6, 4-5).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 31, 'O segundo é este: Amarás o teu próximo como a ti mesmo (Lv. 19, 18). Não há outro mandamento maior do que estes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 32, 'Então o escriba disse-lhe: "Mestre, disseste bem e com verdade que Deus é um só, e que não há outro fora dele;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 33, 'e que o amá-lo com todo o coração, com todo o entendimento, com toda a alma, e com todas as forças, e amar o próximo como a si mesmo, vale mais que todos os holocaustos e sacrifícios."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 34, 'Vendo Jesus que tinha respondido sabiamente, disse-lhe: "Não estás longe do reino de Deus." Desde então, ninguém mais ousava interrogá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 35, 'Continuando a ensinar no templo, Jesus tomou a palavra e disse: "Como dizem os escribas que o Cristo é filho de David?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 36, 'O mesmo David, inspirado pelo Espírito Santo, diz (Ps. 109, 1): Disse o Senhor ao meu Senhor: Senta-te à minha direita, até que eu ponha os teus inimigos por escabelo de teus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 37, 'O mesmo David portanto lhe chama Senhor, como é ele pois seu filho? A grande multidão o ouvia com gosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 38, 'Dizia-lhes ainda nos seus ensinamentos: "Guardai-vos dos escribas, que gostam de andar com roupas largas, de serem saudados nas praças,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 39, 'e de ocuparem as primeiras cadeiras nas sinagogas, e os primeiros lugares nos banquetes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 40, 'que devoram as casas das viúvas, sob o pretexto de longas orações. Serão julgados com maior rigor." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 41, 'Estando Jesus sentado defronte do gazofilácio, observava como o povo deitava ali dinheiro. Muitos ricos deitavam em abundância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 42, 'Tendo chegado uma pobre viúva, lançou duas pequenas moedas, que valem um quarto de um asse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 43, 'Chamando os seus discípulos, disse-lhes: "Na verdade vos digo que esta pobre viúva deu mais que todos os outros que lançaram no gazofilácio,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 44, 'porque todos os outros deitaram do que lhes sobejava, ela porém deitou do seu necessário tudo o que possuía, tudo o que tinha para viver."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Quando saía do templo, disse-lhe um dos seus discípulos: "Olha, Mestre, que pedras e que construções!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Jesus disse-lhe: "Vês estes grandes edifícios? Não ficará pedra sobre pedra, que não seja derribada."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Estando sentado sobre o monte das Oliveiras, defronte do templo, interrogaram-no aparte Pedro, Tiago, João e André:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, '"Diz-nos quando sucederão estas coisas, e que sinal haverá, quando tudo isto estiver para se cumprir?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Então Jesus começou a dizer-lhes : "Vede que ninguém vos engane. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Muitos virão em meu nome, dizendo; Sou eu; e enganarão muitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Quando ouvirdes falar de guerras e de rumores de guerras, não temais; porque importa que estas coisas aconteçam; mas não será ainda o fim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Levantar-se-á nação contra nação, reino contra reino. Haverá terremotos em diversas partes, e fomes. Estas coisas serão o princípio das dores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Tomai, porém, cuidado convosco. Hão-de-vos entregar nos tribunais, sereis açoutados nas sinagogas, sereis, por minha causa, levados diante dos governadores e dos reis, para dar testemunho de mim perante eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Mas, antes, deve o Evangelho ser pregado a todas as nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Quando, pois, vos levarem para vos entregar, não premediteis no que haveis de dizer, mas dizei o que vos for inspirado nessa hora; porque não sois vós que falais, mas o Espírito Santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Então o irmão entregará à morte o seu irmão, o pai o filho; os filhos levantar-se-ão contra os pais e lhes darão a morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Sereis odiados de todos por causa do meu nome. Mas o que perseverar até ao fim, esse será salvo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Quando, pois, virdes a abominação da desolação posta onde não devia estar - leitor, atende bem! - então os que estiverem na Judeia fujam para os montes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'o que estiver sobre o telhado, não desça nem entre para levar coisa alguma de sua casa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'e o que se encontrar no campo, não volte atrás a buscar o seu manto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Ai das mulheres grávidas, e das que tiverem crianças de peito naqueles dias!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Rogai, pois, que não suceda isto no inverno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Porque, naqueles dias, haverá tribulações, quais não houve desde o principio do mundo, que Deus criou, até agora, nem mais haverá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'E se o Senhor não abreviasse aqueles dias, nenhuma pessoa se salvaria; mas ele os abreviou, em atenção aos eleitos que escolheu. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'Então, se alguém vos disser: Eis aqui está o Cristo, ei-lo acolá, não deis crédito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Porque se levantarão falsos cristos e falsos profetas, e farão milagres e prodígios para enganarem, se fosse possível, até os mesmos escolhidos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'Estai, pois, de sobreaviso, eis que eu vos predisse tudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, 'Naqueles dias, depois daquela tribulação, o sol escurecerá, a lua não dará o seu resplendor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'as estrelas cairão do céu, e serão abaladas as potestades que estão nos céus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'Então verão o Filho do homem vir sobre as nuvens, com grande poder e glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 27, 'E enviará logo os seus anjos, e juntará os seus escolhidos dos quatro ventos, desde a extremidade da terra até à extremidade do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Ouvi uma comparação tirada da figueira: Quando os seus ramos estão já tenros e as folhas brotam, sabeis que está perto o estio;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'assim também quando virdes acontecer estas coisas, sabei que (a vinda do Filho do homem para o juízo final) está perto, às portas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'Na verdade vos digo que não passará esta geração, sem que se cumpram todas estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'O céu e a terra passarão, mas as minhas palavras não passarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'A respeito, porém, desse dia ou dessa hora, ninguém sabe, nem os anjos do céu, nem o Filho, mas só o Pai. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 33, 'Estai de sobreaviso, vigiai, porque não sabeis quando será o momento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 34, 'Será como um homem que, empreendendo uma viagem, deixou a sua casa, deu autoridade, aos seus servos, indicando a cada um a sua tarefa, e ordenou ao porteiro que estivesse vigilante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 35, 'Vigiai, pois, visto que não sabeis quando virá o senhor da casa, se de tarde, se à meia-noite, se ao cantar do galo, se pela manhã,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 36, 'para que, vindo de repente, vos não encontre dormindo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 37, 'O que eu, pois, digo a vós, o digo a todos: Vigiai!"');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Dali a dois dias era a Páscoa e os ázimos; os príncipes dos sacerdotes e os escribas andavam buscando modo de o prender por traição, para o matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Porém, diziam: "Não convém que isto se faça no dia da festa, para que se não levante nenhum motim entre o povo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Estando Jesus em Betânia, em casa de Simão o leproso, enquanto estava à mesa, veio uma mulher trazendo um vaso de alabastro cheio de um bálsamo feito de verdadeiro nardo de um grande valor, e, quebrado o vaso, derramou-lho sobre a cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'Alguns dos que estavam presentes indignaram-se, e diziam entre si: "Para que foi este desperdício de bálsamo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'Pois podia vender-se por mais de trezentos dinheiros, e dá-los aos pobres. E irritavam-se contra ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Mas Jesus disse: "Deixai-a. Porque a molestais ? Ela fez-me uma boa obra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'porque vós tereis sempre convosco pobres, e, quando quiserdes, podeis fazer-lhes bem; porém, a mim, não me tendes sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'Ela fez o que podia: embalsamou com antecipação o meu corpo para a sepultura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'Em verdade vos digo: Onde quer que for pregado este Evangelho por todo o mundo, será também contado, para sua memória, o que ela fez."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'Então Judas Iscariotes, um dos doze, foi ter com os príncipes dos sacerdotes, para lhes entregar Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'Eles, ouvindo-o, alegraram-se e prometeram dar-lhe dinheiro. E ele procurava ocasião oportuna para o entregar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'No primeiro dia dos ázimos, quando imolavam a Páscoa, os discípulos lhe disseram: "Onde queres que vamos preparar-te a refeição da Páscoa?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Então ele enviou dois dos seus discípulos, e disse-lhes: "Ide à cidade, e encontrareis um homem levando uma bilha de água; ide atrás dele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'e, onde entrar, dizei ao dono da casa: o Mestre diz: Onde está a minha sala em que eu hei-de comer a Páscoa com os meus discípulos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'E ele vos mostrará uma sala superior, grande, mobilada e posta em ordem. Preparai-me lá o que é preciso."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Os discípulos partiram, chegaram à cidade, encontraram tudo como ele lhes tinha dito, e prepararam a Páscoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'Chegada a tarde, foi Jesus com os doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'Quando estavam à mesa e comiam, disse Jesus: "Em verdade vos digo que um de vós, que come comigo, me há-de entregar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'Então começaram a entristecer-se, e a dizer-lhe cada um de per si: Sou porventura eu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'Ele disse-lhes: É um dos doze que se serve comigo no mesmo prato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'O Filho do homem vai, segundo está escrito dele, mas, ai daquele homem por quem for entregue o Filho do homem! Melhor fora a esse homem não ter nascido."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Enquanto comiam, Jesus tomou pão e, depois de o benzer, partiu-o, deu-lho e disse: "Tomai, isto é o meu corpo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'Em seguida, tendo tomado o cálice, dando graças, deu-lho, e todos beberam dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'E disse-lhes : "Isto é o meu sangue, o sangue da Aliança, que será derramado por muitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 25, 'Em verdade vos digo que não beberei mais desse fruto da vide, até àquele dia em que o beberei novo no reino de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 26, 'Cantados os salmos, foram para o monte das Oliveiras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 27, 'Então, Jesus, disse-lhes: "Todos vos escandalizareis, pois está escrito: Ferirei o pastor, e as ovelhas se dispersarão (Zc. 3, 7).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 28, 'Mas, depois que eu ressuscitar, preceder-vos-ei na Galileia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 29, 'Pedro, porém, disse-lhe: "Ainda que todos se escandalizem a teu respeito, eu não."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 30, 'Jesus disse-lhe: "Em verdade te digo que hoje, nesta mesma noite, antes que o galo cante a segunda vez, me negarás três vezes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 31, 'Porém, ele, insistia ainda mais: "Ainda que me seja preciso morrer contigo, não te negarei." E todos diziam o mesmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 32, 'Chegando a uma herdade, chamada Getsemani, Jesus disse a seus discípulos: "Sentai-vos aqui enquanto vou orar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 33, 'Levou consigo Pedro, Tiago e João; e começou a sentir pavor e angústia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 34, 'E disse-lhes: "A minha alma está numa tristeza mortal; ficai aqui, e vigiai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 35, 'Tendo-se adiantado um pouco, prostrou-se por terra, e pedia que, se era possível, se afastasse dele aquela hora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 36, 'Dizia: "Abba, Pai, todas as coisas te são possíveis; afasta de mim este cálice; porém, não se faça o que eu quero, mas o que tu queres." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 37, 'Depois voltou, e encontrou-os dormindo, e disse a Pedro: "Simão, dormes? Não pudeste vigiar uma hora?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 38, 'Vigiai e orai, para que não entreis em tentação. O espirito na verdade está pronto, mas a carne é fraca."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 39, 'Tendo-se retirado novamente, pôs-se a orar, repetindo as mesmas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 40, 'Voltando, encontrou-os outra vez a dormir, porque tinham os olhos pesados. Não sabiam que responder-lhe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 41, 'Voltou terceira vez, e disse-lhes: "Dormi agora e descansai. Basta, é chegada a hora; eis que o Filho do homem vai ser entregue nas mãos dos pecadores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 42, 'Levantai-vos, vamos; eis que se aproxima o que me há-de entregar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 43, 'Ainda falava, quando chega Judas Iscariotes, um dos doze, e com ele muita gente armada de espadas e varapaus, enviada pelos príncipes dos sacerdotes, pelos escribas e pelos anciães.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 44, 'O traidor tinha-lhes dado uma senha, dizendo: "Aquele a quem eu oscular, é esse; prendei-o, e levai-o com cuidado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 45, 'Logo que chegou, aproximando-se imediatamente de Jesus, disse-lhe: "Mestre!" e osculou-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 46, 'Então eles lançaram-lhe as mãos, e prenderam-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 47, 'Um dos circunstantes, tirando da espada, feriu um servo do sumo sacerdote, e cortou-lhe uma orelha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 48, 'Jesus, tomando a palavra, disse-lhes: "Como se eu fosse um ladrão, viestes com espadas e varapaus a prender-me?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 49, 'Todos os dias estava entre vós ensinando no templo, e não me prendestes. Mas isto acontece para que se cumpram as Escrituras."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 50, 'Então os seus discípulos, abandonando-o, fugiram todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 51, 'Um jovem seguia Jesus coberto sòmente com um lençol, e prenderam-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 52, 'Mas ele, largando o lençol, escapou-se-lhes nu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 53, 'Levaram Jesus ao sumo sacerdote, e juntaram-se todos os príncipes dos sacerdotes, os anciães e os escribas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 54, 'Pedro foi-o seguindo de longe, até dentro do pátio do sumo sacerdote. Estava sentado ao fogo com os criados, e aquecia-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 55, 'Os príncipes dos sacerdotes e todo o conselho buscavam algum testemunho contra Jesus, para o fazerem morrer, e não o encontravam,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 56, 'Porque muitos depunham falsamente contra ele, mas não concordavam os seus depoimentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 57, 'Levantando-se uns certos, depunham falsamente contra ele, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 58, '"Nós ouvimos-lhe dizer: Destruirei este templo, feito pela mão do homem, e em três dias edificarei outro, que não será feito pela mão do homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 59, 'Porém nem este seu testemunho era concorde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 60, 'Então, levantando-se no meio da assembleia o sumo sacerdote, interrogou Jesus, dizendo: "Não respondes nada? O que é que estes depõem contra ti?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 61, 'Ele, porém, estava em silêncio, e nada respondeu. Interrogou-o de novo o sumo sacerdote, e disse-lhe: "És tu o Cristo, o Filho de Deus bendito?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 62, 'Jesus respondeu: "Eu o sou, e vereis o Filho do homem sentado á direita do poder de Deus, e vir sobre as nuvens do céu (Ps. 109, 1 ; Dn. 7, 13)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 63, 'Então o sumo sacerdote, rasgando os seus vestidos, disse: "Que necessidade temos de mais testemunhas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 64, 'Ouvistes a blasfêmia. Que vos parece?" E todos o condenaram como réu de morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 65, 'Então começaram alguns a cuspir-lhe, a velar-lhe o rosto, e a dar-lhe punhadas, dizendo-lhe: "Profetiza!" Os criados receberam-no a bofetadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 66, 'Entretanto, estando Pedro em baixo no átrio, chegou uma das criadas do sumo sacerdote.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 67, 'Vendo Pedro, que se aquecia, encarando nele, disse: "Tu também estavas com Jesus Nazareno."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 68, 'Mas ele negou: "Não sei, nem compreendo o que dizes." E saiu fora para a entrada do pátio, e o galo cantou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 69, 'Tendo-o visto a criada, começou novamente a dizer aos que estavam presentes: "Este é daqueles."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 70, 'Mas ele o negou de novo. Pouco depois, os que ali estavam diziam de novo a Pedro: "Verdadeiramente tu és um deles, porque és galileu."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 71, 'Ele começou a fazer imprecações e a jurar: "Não conheço esse homem de quem falais."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 72, 'Imediatamente cantou o galo segunda vez. Pedro recordou-se da palavra que Jesus tinha dito: "Antes que o galo cante duas vezes, me negarás três vezes." E começou a chorar.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Logo pela manhã, tiveram conselho os príncipes dos sacerdotes com os anciães, os escribas e com todo o Sinédrio. Manietando Jesus, o levaram e entregaram a Pilatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Pilatos perguntou-lhe: "Tu és o Rei dos Judeus?" Ele respondeu-lhes: "Tu o dizes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Os príncipes dos sacerdotes acusavam-no de muitas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Pilatos interrogou-o novamente: "Não respondes coisa alguma? Vê de quantas coisas te acusam."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Mas Jesus não respondeu mais nada, de sorte que Pilatos estava admirado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Ora ele costumava no dia da festa (de Páscoa) soltar-lhes um dos presos, qualquer que eles pedissem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Havia um chamado Barrabás, que estava preso com outros sediciosos, o qual, num motim, tinha cometido um homicídio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'Juntando-se o povo, começou a pedir o (indulto) que sempre lhes concedia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'Pilatos respondeu-lhes: "Quereis que vos solte o Rei dos Judeus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'Porque sabia que os príncipes dos sacerdotes o tinham entregado por inveja.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Porém, os príncipes dos sacerdotes, incitaram o povo a que pedisse antes a liberdade de Barrabás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'Pilatos, falando outra vez, disse-lhes: "Que quereis pois que eu faça ao Rei dos Judeus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'Eles tornaram a gritar: "Crucifica-o!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Pilatos, porém, dizia-lhes: "Que mal fez ele?" Mas eles cada vez gritavam mais: "Crucifica-o!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Então Pilatos, querendo satisfazer o povo, soltou-lhes Barrabás. Depois de fazer açoutar Jesus, entregou-o para ser crucificado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Os soldados conduziram-no ao interior do átrio, isto é, ao Pretório, e ali juntaram toda a coorte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Revestiram-no de púrpura e cingiram-lhe a cabeça com uma coroa entretecida de espinhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'E começaram a saudá-lo: "Salve, Rei dos Judeus!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'E davam-lhe na cabeça com uma cana, cuspiam-lhe no rosto, e, pondo-se de joelhos, faziam-lhe reverências.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Depois de o terem escarnecido, despojaram-no da púrpura, vestiram-lhe os seus vestidos, e levaram-no para o crucificar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'Obrigarem um certo homem que a a passar, Simão de Cirene, que vinha do campo, pai de Alexandre e de Rufo, a levar a cruz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Conduziram-no ao lugar do Gólgota, que quer dizer lugar do Crânio. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Davam-lhe a beber vinho misturado com mirra, mas ele não o tomou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'Tendo-o crucificado, dividiram os seus vestidos, lançando sortes sobre eles, para ver a parte que cada um levaria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'Era a hora tércia quando o crucificaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'A causa da sua condenação estava escrita nesta inscrição: O REI DOS JUDEUS.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'Com ele crucificaram dois ladrões, um à sua direita, e outro à esquerda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 28, 'Cumpriu-se a Escritura, que diz: Foi contado entre os maus (Is. 53, 12). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 29, 'Os que iam passando blasfemavam, abanando as suas cabeças, e dizendo: "Ah! tu, que destróis o templo de Deus, e o reedificas em três dias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 30, 'salva-te a ti mesmo, descendo da cruz."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 31, 'Do mesmo modo, escarnecendo-o também os príncipes dos sacerdotes e os escribas, diziam entre si: "Salvou os outros, e não se pode salvar a si mesmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 32, 'O Cristo, o Rei de Israel desça agora da cruz, para que vejamos e acreditemos." Também os que tinham sido crucificados com ele o insultavam. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 33, 'Chegada a hora sexta, cobriu-se toda a terra de trevas até à hora nona.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 34, 'E, à hora nona, exclamou Jesus em alta voz: "Eloí, Eloí, lamma sabachtani?" que quer dizer: "Deus meu. Deus meu, porque me desamparaste?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 35, 'Ouvindo isto, alguns dos circunstantes diziam: "Eis que chama por Elias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 36, 'Correndo um, e ensopando uma esponja em vinagre, e atando-a numa cana, dava-lhe de beber, dizendo: "Deixai, vejamos se Elias vem tirá-lo." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 37, 'Mas Jesus, dando um grande brado, expirou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 38, 'O véu do templo rasgou-se em duas partes, de alto a baixo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 39, 'O centurião, que estava defronte, vendo que Jesus expirava dando este brado, disse: "Verdadeiramente este homem era Filho de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 40, 'Encontravam-se também ali algumas mulheres vindo de longe, entre as quais estava Maria Madalena, Maria, mãe de Tiago menor e de José, e Salomé,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 41, 'as quais já o seguiam e serviam quando ele estava na Galileia, e muitas outras, que, juntamente com ele, tinham subido a Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 42, 'Quando era já tarde - pois era a Preparação, isto é, a vigília de sábado - ,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 43, 'foi José de Arimateia, membro ilustre do Sinédrio, que também esperava o reino de Deus, apresentou-se corajosamente a Pilatos, e pediu-lhe o corpo de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 44, 'Pilatos admirou-se de que estivesse já morto; mandando chamar o centurião, perguntou-lhe se estava já morto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 45, 'Informado pelo centurião, deu o corpo a José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 46, 'José, tendo comprado um lençol, e tirando-o da cruz, envolveu-o no lençol, depositou-o num sepulcro, que estava aberto na rocha, e rolou uma pedra para diante da boca do sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 47, 'Entretanto Maria Madalena e Maria, mãe de José, estavam observando onde era depositado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Passado o dia de sábado, Maria Madalena, Maria, mãe de Tiago, e Salomé compraram aromas para irem embalsamar Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Partindo no primeiro dia da semana, de manhã cedo, chegaram ao sepulcro, quando o sol já era nascido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'Diziam entre si: "Quem nos há-de revolver a pedra da boca do sepulcro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Mas, olhando, viram revolvida a pedra, que era muito grande.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Entrando no sepulcro, viram um jovem sentado do lado direito, vestido de uma túnica branca, e ficaram assustadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Ele disse-lhes: "Não temais. Buscais a Jesus Nazareno, o crucificado? Ressuscitou, não está aqui. Eis o lugar onde o depositaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Mas ide, dizei a seus discípulos, e especialmente a Pedro, que ele vai adiante de vós para a Galileia; lá o vereis, como ele vos disse."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'Elas, saindo do sepulcro, fugiram, porque as tinha assaltado o temor e estavam fora de si. Não disseram nada a ninguém, tal era o medo que tinham.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Jesus tendo ressuscitado de manhã, no primeiro dia da semana, apareceu primeiramente a Maria Madalena, da qual tinha expulsado sete demônios. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'Ela foi noticiá-lo aos que tinham andado com ele, os quais estavam aflitos e chorosos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Tendo eles ouvido dizer que Jesus estava vivo, e que fora visto por ela, não acreditaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'Depois disto, mostrou-se sob outra forma a dois deles, enquanto iam para a aldeia;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'os quais foram anunciar aos outros, que nem a estes deram crédito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Finalmente apareceu aos onze, quando estavam à mesa, e censurou-lhes a sua incredulidade e dureza de coração, por não terem dado crédito aos que o viram ressuscitado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Disse-lhes: "Ide por todo o mundo, pregai o Evangelho a toda a criatura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'O que crer e for batizado, será salvo; o que, porém, não crer, será condenado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Eis os milagres que acompanharão os que crerem: Expulsarão os demônios em meu nome, falarão novas línguas, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'manusearão as serpentes, e, se beberem alguma coisa mortífera, não lhes fará mal; imporão as mãos sobre os enfermos, e serão curados." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'O Senhor, depois que assim lhes falou, elevou-se ao céu, e foi sentar-se à direita de Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'Eles, tendo partido, pregaram por toda a parte, cooperando com eles o Senhor, e confirmando a palavra com os milagres que a acompanhavam.');
